  Periods: {title:'How cycle length is counted',text:'Count from the first day of one period to the day before the next period starts. Your own logged dates help make estimates more personal.',source:'NHS · Menstrual cycle',href:'https://www.nhs.uk/conditions/periods/fertility-in-the-menstrual-cycle/',art:'journal'},
  'Food & movement': {title:'Small steps count',text:'A balanced eating pattern can be considered over a day or week; it does not have to be perfect at every meal. Choose foods and movement that work for you.',source:'NHS · Eatwell Guide',href:'https://www.nhs.uk/live-well/eat-well/food-guidelines-and-food-labels/the-eatwell-guide/',art:'nourish'},
