  const monthPeriodDays=monthDates.filter(date=>markers(date).includes('period')).length;
  const monthFertileDays=monthDates.filter(date=>markers(date).includes('fertile')).length;
  const selectedTypes=markers(dateAtNoon(selectedDate));
  const loggedItemsCount=data.pt_cycles.length+data.pt_diet.length+data.pt_exercise.length+data.pt_symptoms.length+data.pt_medication.length;
